steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      issues(filter: { search: { _eq: \"security review\" }, assignee: { email: { _eq: \"priya@vendorworks.example\" } } }) {
        nodes {
          id
          identifier
          title
          priority
          assignee { id name email }
          team { name }
        }
      }
      users(filter: { name: { _contains: \"Priya\" } }) {
        nodes {
          id
          name
          email
        }
      }
    }"
  }'
